//! A private Sigstore generated by `fixtures/generate.py`: a P-384 CA, an
//! `openssl ts` timestamp authority and a Rekor v2 log with an Ed25519 or
//! ECDSA key, all signing `fixtures/MANIFEST`. The anchors come from the
//! signer, so a private deployment needs nothing from the verifier but its own
//! statement.

#![allow(clippy::unwrap_used)]

use std::fs;
use std::path::PathBuf;

use base64::Engine as _;
use base64::engine::general_purpose::STANDARD as BASE64;
use serde_json::Value;
use sha2::{Digest as _, Sha256};
use surrealism_verify::{Error, ManifestDigest, Signer, SigstoreSigner, VerifiedSigner, verify};

const IDENTITY: &str =
	"https://github.com/acme/color/.github/workflows/release.yml@refs/tags/v1.0.0";

fn path(name: &str) -> PathBuf {
	PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures").join(name)
}

fn digest() -> ManifestDigest {
	Sha256::digest(fs::read(path("MANIFEST")).unwrap()).into()
}

fn bundle(case: &str) -> Vec<u8> {
	fs::read(path(&format!("private/{case}/bundle.sigstore.json"))).unwrap()
}

fn signer(case: &str) -> SigstoreSigner {
	let json: Value =
		serde_json::from_slice(&fs::read(path(&format!("private/{case}/signer.json"))).unwrap())
			.unwrap();
	let bytes = |v: &Value| BASE64.decode(v.as_str().unwrap()).unwrap();
	let list = |v: &Value| v.as_array().unwrap().iter().map(bytes).collect();
	let text = |v: &Value| v.as_str().map(str::to_string);
	SigstoreSigner {
		ca: list(&json["ca"]),
		log: bytes(&json["log"]),
		tsa: list(&json["tsa"]),
		issuer: text(&json["issuer"]).unwrap(),
		identity: text(&json["identity"]).unwrap(),
		repository_id: text(&json["repository_id"]),
		owner_id: text(&json["owner_id"]),
	}
}

fn check(bundle: &[u8], signer: SigstoreSigner) -> Result<VerifiedSigner, Error> {
	verify(&digest(), bundle, &Signer::Sigstore(signer))
}

/// Applies `edit` to the bundle's JSON.
fn edited(case: &str, edit: impl FnOnce(&mut Value)) -> Vec<u8> {
	let mut json: Value = serde_json::from_slice(&bundle(case)).unwrap();
	edit(&mut json);
	serde_json::to_vec(&json).unwrap()
}

fn entry(json: &mut Value) -> &mut Value {
	&mut json["verificationMaterial"]["tlogEntries"][0]
}

#[test]
fn ed25519_log() {
	let VerifiedSigner::Sigstore {
		identity,
		repository_id,
		owner_id,
		log_index,
		..
	} = check(&bundle("ed25519-log"), signer("ed25519-log")).unwrap()
	else {
		panic!("not a Sigstore result");
	};
	assert_eq!(identity, IDENTITY);
	assert_eq!(repository_id.as_deref(), Some("812345678"));
	assert_eq!(owner_id.as_deref(), Some("98765432"));
	assert_eq!(log_index, 4);
}

#[test]
fn ecdsa_log() {
	check(&bundle("ecdsa-log"), signer("ecdsa-log")).unwrap();
}

/// A certificate without repository IDs, such as one for an email identity,
/// verifies against a signer that records none.
#[test]
fn email_identity_without_ids() {
	let verified = check(&bundle("email-identity"), signer("email-identity")).unwrap();
	assert!(matches!(
		verified,
		VerifiedSigner::Sigstore { repository_id: None, owner_id: None, ref identity, .. }
			if identity == "release@acme.test"
	));
	let mut demanding = signer("email-identity");
	demanding.repository_id = Some("812345678".into());
	assert_eq!(
		check(&bundle("email-identity"), demanding),
		Err(Error::Identity {
			field: "repository_id"
		})
	);
}

/// A signer that records no IDs does not accept a certificate that carries
/// them: the IDs are what protect against a renamed and re-registered
/// repository.
#[test]
fn missing_ids_in_signer_refuse_a_certificate_with_ids() {
	let mut lax = signer("ed25519-log");
	lax.repository_id = None;
	lax.owner_id = None;
	assert_eq!(
		check(&bundle("ed25519-log"), lax),
		Err(Error::Identity {
			field: "repository_id"
		})
	);
}

#[test]
fn wrong_id() {
	let mut s = signer("ed25519-log");
	s.owner_id = Some("98765433".into());
	assert_eq!(
		check(&bundle("ed25519-log"), s),
		Err(Error::Identity {
			field: "owner_id"
		})
	);
}

/// The certificate was valid for 10 minutes, two hours before the timestamp.
#[test]
fn expired_time() {
	assert_eq!(check(&bundle("expired"), signer("expired")), Err(Error::OutsideValidity));
}

#[test]
fn wrong_log_key() {
	// Each log's key against the other log's checkpoint.
	let mut s = signer("ed25519-log");
	s.log = signer("ecdsa-log").log;
	assert!(matches!(check(&bundle("ed25519-log"), s), Err(Error::Log(_))));
	let mut s = signer("ecdsa-log");
	s.log = signer("ed25519-log").log;
	assert!(matches!(check(&bundle("ecdsa-log"), s), Err(Error::Log(_))));
}

#[test]
fn tampered_digest() {
	for case in ["ed25519-log", "ecdsa-log"] {
		let mut digest = digest();
		digest[7] ^= 0x10;
		assert_eq!(
			verify(&digest, &bundle(case), &Signer::Sigstore(signer(case))),
			Err(Error::DigestMismatch)
		);
	}
}

#[test]
fn tampered_entry_body() {
	// A body that records another digest hashes to another leaf.
	let body = edited("ed25519-log", |json| {
		let entry = entry(json);
		let raw = BASE64.decode(entry["canonicalizedBody"].as_str().unwrap()).unwrap();
		let text = String::from_utf8(raw).unwrap().replace("\"SHA2_256\"", "\"SHA2_384\"");
		entry["canonicalizedBody"] = BASE64.encode(text).into();
	});
	assert!(matches!(check(&body, signer("ed25519-log")), Err(Error::Log(_))));
}

#[test]
fn tampered_inclusion_proof() {
	let cases: [fn(&mut Value); 4] = [
		|json| entry(json)["inclusionProof"]["hashes"][0] = BASE64.encode([0u8; 32]).into(),
		|json| entry(json)["inclusionProof"]["logIndex"] = "5".into(),
		|json| entry(json)["inclusionProof"]["treeSize"] = "8".into(),
		|json| {
			entry(json)["inclusionProof"]["hashes"].as_array_mut().unwrap().pop();
		},
	];
	for edit in cases {
		let bundle = edited("ed25519-log", edit);
		let err = check(&bundle, signer("ed25519-log")).unwrap_err();
		assert!(matches!(err, Error::Log(_)), "{err:?}");
	}
}

#[test]
fn tampered_checkpoint() {
	let bundle = edited("ed25519-log", |json| {
		let checkpoint = &mut entry(json)["inclusionProof"]["checkpoint"]["envelope"];
		let text = checkpoint.as_str().unwrap().replacen("\n7\n", "\n8\n", 1);
		*checkpoint = text.into();
	});
	assert!(matches!(check(&bundle, signer("ed25519-log")), Err(Error::Log(_))));
}

/// The signature line's key hint and signature are right, but it names
/// another origin.
#[test]
fn checkpoint_signed_under_another_name() {
	let bundle = edited("ed25519-log", |json| {
		let checkpoint = &mut entry(json)["inclusionProof"]["checkpoint"]["envelope"];
		let text = checkpoint
			.as_str()
			.unwrap()
			.replace("\u{2014} log.surrealism.test ", "\u{2014} log.evil.test ");
		*checkpoint = text.into();
	});
	assert!(matches!(check(&bundle, signer("ed25519-log")), Err(Error::Log(_))));
}

/// The signature and the logged certificate belong together, but the bundle
/// presents another certificate.
#[test]
fn swapped_certificate() {
	let other = {
		let json: Value = serde_json::from_slice(&bundle("ecdsa-log")).unwrap();
		json["verificationMaterial"]["certificate"].clone()
	};
	let bundle = edited("ed25519-log", |json| json["verificationMaterial"]["certificate"] = other);
	assert_eq!(check(&bundle, signer("ed25519-log")), Err(Error::BadSignature));
}

#[test]
fn anchor_lists() {
	let b = bundle("ed25519-log");
	// The intermediate alone is a sufficient `ca` anchor.
	let mut s = signer("ed25519-log");
	s.ca.truncate(1);
	check(&b, s).unwrap();
	// The root alone is not: a v0.3 bundle carries only the leaf.
	let mut s = signer("ed25519-log");
	s.ca.remove(0);
	assert!(matches!(check(&b, s), Err(Error::Chain(_))));
	// Order does not matter.
	let mut s = signer("ed25519-log");
	s.ca.reverse();
	s.tsa.reverse();
	check(&b, s).unwrap();
	// The timestamp's signing certificate must itself be an anchor.
	let mut s = signer("ed25519-log");
	s.tsa.remove(0);
	assert!(matches!(check(&b, s), Err(Error::Timestamp(_))));
	// An empty list is an invalid signer.
	let mut s = signer("ed25519-log");
	s.ca.clear();
	assert!(matches!(check(&b, s), Err(Error::InvalidSigner(_))));
	// So is a log key that is not a key.
	let mut s = signer("ed25519-log");
	s.log = b"not a key".to_vec();
	assert!(matches!(check(&b, s), Err(Error::InvalidSigner(_))));
}

#[test]
fn oversized_signature() {
	let mut b = bundle("ed25519-log");
	b.resize(surrealism_verify::MAX_SIGNATURE_LEN + 1, b' ');
	assert_eq!(check(&b, signer("ed25519-log")), Err(Error::TooLarge));
}

/// The byte range of the DER element at `at`.
fn element(der: &[u8], at: usize) -> std::ops::Range<usize> {
	let (header, len) = match der[at + 1] {
		n if n < 0x80 => (2, usize::from(n)),
		n => {
			let count = usize::from(n & 0x7f);
			let len =
				der[at + 2..at + 2 + count].iter().fold(0, |acc, &b| (acc << 8) | usize::from(b));
			(2 + count, len)
		}
	};
	at..at + header + len
}

/// The range of the TSTInfo inside a timestamp: the content of the OCTET
/// STRING inside the `[0]` that follows the first `id-ct-TSTInfo` OID.
fn tst_info(der: &[u8]) -> std::ops::Range<usize> {
	const OID: &[u8] =
		&[0x06, 0x0b, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x09, 0x10, 0x01, 0x04];
	let explicit = der.windows(OID.len()).position(|w| w == OID).unwrap() + OID.len();
	let octets = explicit + header_len(der, explicit);
	let tst = octets + header_len(der, octets);
	element(der, tst)
}

fn header_len(der: &[u8], at: usize) -> usize {
	match der[at + 1] {
		n if n < 0x80 => 2,
		n => 2 + usize::from(n & 0x7f),
	}
}

/// Corrupting a byte never panics. Corrupting a byte that a signature covers
/// is always refused: anywhere in the leaf certificate, in the TSTInfo, or in
/// the timestamp's signature. Bytes nothing signs, such as the certificates a
/// timestamp embeds and the verifier ignores, may change freely.
#[test]
fn corrupted_der_is_refused() {
	let original: Value = serde_json::from_slice(&bundle("ed25519-log")).unwrap();
	let fields: [fn(&mut Value) -> &mut Value; 2] = [
		|json| &mut json["verificationMaterial"]["certificate"]["rawBytes"],
		|json| {
			&mut json["verificationMaterial"]["timestampVerificationData"]["rfc3161Timestamps"][0]["signedTimestamp"]
		},
	];
	for (n, field) in fields.into_iter().enumerate() {
		let mut json = original.clone();
		let der = BASE64.decode(field(&mut json).as_str().unwrap()).unwrap();
		let signed: [std::ops::Range<usize>; 2] = if n == 0 {
			[0..der.len(), 0..0]
		} else {
			// The ECDSA signature value and its algorithm close the token.
			[tst_info(&der), der.len() - 80..der.len()]
		};
		for i in (0..der.len()).step_by(5) {
			let mut corrupted = der.clone();
			corrupted[i] ^= 0x01;
			*field(&mut json) = BASE64.encode(&corrupted).into();
			let result = check(&serde_json::to_vec(&json).unwrap(), signer("ed25519-log"));
			if signed.iter().any(|r| r.contains(&i)) {
				assert!(result.is_err(), "field {n}: flipping byte {i} was accepted");
			}
		}
	}
}

/// A bundle may make the verifier check only a bounded number of signatures.
#[test]
fn bounded_work() {
	let timestamps = edited("ed25519-log", |json| {
		let list =
			&mut json["verificationMaterial"]["timestampVerificationData"]["rfc3161Timestamps"];
		let one = list[0].clone();
		*list = Value::Array(vec![one; 5]);
	});
	assert!(matches!(check(&timestamps, signer("ed25519-log")), Err(Error::Malformed(_))));

	let entries = edited("ed25519-log", |json| {
		let list = &mut json["verificationMaterial"]["tlogEntries"];
		let one = list[0].clone();
		*list = Value::Array(vec![one; 5]);
	});
	assert!(matches!(check(&entries, signer("ed25519-log")), Err(Error::Malformed(_))));

	let lines = edited("ed25519-log", |json| {
		let checkpoint = &mut entry(json)["inclusionProof"]["checkpoint"]["envelope"];
		let text = checkpoint.as_str().unwrap().to_string();
		let line = text.lines().last().unwrap().to_string();
		*checkpoint = format!("{text}{}", format!("{line}\n").repeat(16)).into();
	});
	assert!(matches!(check(&lines, signer("ed25519-log")), Err(Error::Log(_))));
}

/// Numbers are protobuf JSON `int64` strings: decimal digits only.
#[test]
fn signed_numbers_are_refused() {
	let bundle = edited("ed25519-log", |json| {
		entry(json)["inclusionProof"]["treeSize"] = "+7".into();
	});
	assert!(matches!(check(&bundle, signer("ed25519-log")), Err(Error::Malformed(_))));
}
